export function updateCanvasEngineState(newState) {
  if (newState.speedKmh !== undefined) {
    canvasEngineState.sceneSpeedKmh = newState.speedKmh;
    canvasEngineState.intensity = Math.min(Math.max(newState.speedKmh / 115, 0), 1);
  }
  if (newState.acceleration !== undefined) {
    canvasEngineState.sceneAccelerationMs2 = newState.acceleration;
  }
  if (newState.shiftProgress !== undefined) {
    canvasEngineState.shiftProgress = newState.shiftProgress;
  }
  if (newState.shiftWay !== undefined) {
    canvasEngineState.shiftWay = newState.shiftWay;
  }
  if (newState.roadReveal !== undefined) {
    canvasEngineState.roadReveal = newState.roadReveal;
  }
  if (newState.introTravel !== undefined) {
    canvasEngineState.introTravel = newState.introTravel;
  }
  if (newState.isDark !== undefined) {
    canvasEngineState.isDark = newState.isDark;
  }
}

